"""Tests for the corpus generator and vocabulary builder (seed 99)."""

import csv
import pytest

from corpus_gen import NUM_TOKENS, STOPWORDS, generate_corpus
from vocab_build import VOCAB_CSV, build_vocab, read_tokens

SEED = 99


@pytest.fixture(scope="module")
def built():
    generate_corpus(SEED)
    build_vocab()
    with open(VOCAB_CSV, newline="") as fh:
        rows = list(csv.DictReader(fh))
    return rows


def read_int(row, key):
    return int(row[key])


def read_float(row, key):
    return float(row[key])


def test_token_accounting(built):
    tokens = read_tokens()
    stop_occurrences = sum(t in STOPWORDS for t in tokens)
    assert sum(read_int(r, "count") for r in built) + stop_occurrences == NUM_TOKENS


def test_coverage_monotone_and_complete(built):
    cov = [read_float(r, "cumulative_coverage") for r in built]
    assert all(b >= a for a, b in zip(cov, cov[1:]))
    assert cov[-1] == pytest.approx(1.0, abs=1e-9)


def test_rank1_highest_count(built):
    counts = [read_int(r, "count") for r in built]
    assert max(counts) == counts[0]
    assert counts == sorted(counts, reverse=True)


def test_no_stopwords_in_csv(built):
    words = {r["word"] for r in built}
    assert not words & set(STOPWORDS)


def test_top50_zipf_coverage(built):
    tokens = read_tokens()
    total_nonstop = sum(t not in STOPWORDS for t in tokens)
    top50 = sum(read_int(r, "count") for r in built[:50])
    assert top50 / total_nonstop >= 0.55

